import React from 'react';
import styled from 'styled-components';
import Layout from '../components/Layout';
import { Button, Input, Popconfirm, Space, Table, Tag, Tooltip, Typography, message } from 'antd';
import { DeleteOutlined, DownloadOutlined, LineChartOutlined, TableOutlined } from '@ant-design/icons';
import { parseComparisonTaskIds } from '../components/patternComparison.mjs';
import { runAfterSuccess } from '../components/submitHelpers.mjs';
import { retryTask } from '../components/ResultWorkflows';
import { API as URL } from '../components/QuickRefineProgress';
import { adoptedLabel, adoptedRwp, formatFixed, phasesLabel, phasesTooltip, stateLabel, tasksQuery } from '../components/resultsList.mjs';
import { overallColor, overallLabel } from '../components/confidence.mjs';
import { StateTag } from '../components/ConfidenceViews';

/** Status tag of a completed task followed by its overall confidence (same labels as the task page). */
function ConfidenceStatus({ tag, level }) {
  const label = overallLabel(level);
  if (!label) return tag;
  // A verdict only exists for completed tasks, so it stands in for the plain "Completed" text.
  return <Tooltip title="Completed. Open the task for the reasons.">
    <Tag color={overallColor(level)}>{label}</Tag>
  </Tooltip>;
}

const Container = styled.div`
`

const { Search } = Input;

// Failed and cancelled rows have no metrics; their cells are left empty and dimmed.
const hasNoResult = entry => ['FIZZLED', 'CANCELLED'].includes(entry.state);
const metricCell = entry => ({ className: hasNoResult(entry) ? 'dara-dim' : '' });
const STATE_FILTERS = ['COMPLETED', 'FIZZLED', 'RUNNING', 'READY', 'CANCELLING', 'CANCELLED'].map(value => ({ text: stateLabel(value), value }));

function ResultsPage({ location }) {
  const queryParameters = new URLSearchParams(location.search)
  const page = Number((queryParameters.get('page')) || "1")
  const limit = Number(queryParameters.get('limit') || "10")
  const [ user, setUser ] = React.useState(queryParameters.get('user') || null)
  const [ name, setName ] = React.useState(queryParameters.get('name') || null)

  const [data, setData] = React.useState({})
  const [selectedTaskIds, setSelectedTaskIds] = React.useState(() => parseComparisonTaskIds(queryParameters.get('selected')));

  const onSearch = (value) => {
    setUser(value)
    window.location.href = `/results?` + tasksQuery({ page: 1, limit, user: value, name, selected: selectedTaskIds })
  }

  const onNameSearch = (value) => {
    const trimmed = (value || '').trim()
    setName(trimmed || null)
    window.location.href = `/results?` + tasksQuery({ page: 1, limit, user, name: trimmed, selected: selectedTaskIds })
  }

  React.useEffect(() => {
    fetch(`${URL}/tasks?page=${page}&limit=${limit}` + (user ? `&user=${encodeURIComponent(user)}` : "") + (name ? `&name=${encodeURIComponent(name)}` : ""))
      .then(response => response.json())
      .then(data => setData(data));
  }, [page, limit, user, name]);

  const deleteTask = async (taskId) => {
    const response = await fetch(`${URL}/task/${taskId}`, { method: 'DELETE' });
    if (!response.ok) {
      const error = await response.json();
      message.error(error.detail || 'Could not delete the result.');
      return;
    }
    // The result is already deleted on the server; UI follow-up problems must not look like a failed delete.
    runAfterSuccess([
      () => setData(previous => ({
        ...previous,
        tasks: (previous.tasks || []).filter(task => task.fw_id !== taskId),
        total_tasks: Math.max((previous.total_tasks || 1) - 1, 0),
      })),
      () => setSelectedTaskIds(previous => previous.filter(id => id !== taskId)),
      () => message.success(`Task ${taskId} deleted.`),
    ]);
  };

  const columns = [
    {
      title: 'ID',
      dataIndex: 'fw_id',
      key: 'fw_id',
      className: 'dara-num',
    },
    {
      title: 'Name',
      dataIndex: 'name',
      key: 'name',
      render: (text, entry) => (
        <>
          <a href={`/task?id=${entry.fw_id}`}>{text}</a>
          {entry.series?.id ? (
            <div>
              <Tag style={{ marginTop: 4 }}>
                <a href={`/series/?id=${encodeURIComponent(entry.series.id)}`}>{`Series: ${entry.series.name} #${(entry.series.order ?? 0) + 1}`}</a>
              </Tag>
            </div>
          ) : null}
        </>
      )
    },
    {
      title: 'Status',
      dataIndex: 'state',
      key: 'state',
      filters: STATE_FILTERS,
      onFilter: (value, entry) => entry.state === value,
      render: (text, entry) => {
        const tag = <StateTag state={text} key={text} />
        const shown = text === 'FIZZLED' && entry.error_summary?.title
          ? <Tooltip title={entry.error_summary.title}>{tag}</Tooltip>
          : tag
        return text === 'FIZZLED' ? <Space size={4}>
          {shown}
          {entry.error_summary?.remedy?.label ? <Popconfirm
            title={`Retry task ${entry.fw_id} with the suggested fix (${entry.error_summary.remedy.label})?`}
            description="A new task is queued; the failed task is kept."
            okText="Retry with fix"
            cancelText="Cancel"
            onConfirm={() => retryTask(entry.fw_id, true)}
          ><Button type="link" size="small" style={{ padding: 0 }}>Retry with fix</Button></Popconfirm> : null}
          <Button type="link" size="small" style={{ padding: 0 }} href={`/?clone_task=${entry.fw_id}`}>Rerun</Button>
        </Space> : <ConfidenceStatus tag={shown} level={text === 'COMPLETED' ? entry.summary?.confidence_overall : null} />
      }
    },
    {
      title: <Tooltip title="Rwp of the adopted fit, or of the automatic fit when nothing is adopted"><span>Rwp (adopted) (%)</span></Tooltip>,
      key: 'best_rwp',
      className: 'dara-num',
      onCell: metricCell,
      render: (_, entry) => (hasNoResult(entry) ? null : formatFixed(adoptedRwp(entry.summary))),
    },
    {
      title: 'GOF',
      key: 'gof',
      className: 'dara-num',
      onCell: metricCell,
      render: (_, entry) => (hasNoResult(entry) ? null : formatFixed(entry.summary?.gof)),
    },
    {
      title: 'Final phases',
      key: 'final_phases',
      width: 240,
      onCell: metricCell,
      render: (_, entry) => {
        const label = phasesLabel(entry.summary)
        if (!label) return hasNoResult(entry) ? null : '—'
        return (
          <Tooltip title={<div style={{ whiteSpace: 'pre-line' }}>{phasesTooltip(entry.summary)}</div>}>
            <span style={{ display: 'inline-block', maxWidth: 240, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', verticalAlign: 'bottom' }}>{label}</span>
          </Tooltip>
        )
      }
    },
    {
      title: <Tooltip title="Result marked as adopted in the task review">Adopted</Tooltip>,
      key: 'adopted',
      onCell: metricCell,
      render: (_, entry) => {
        const label = adoptedLabel(entry.adopted)
        return label ? <Tag color={label.color}>{label.text}</Tag> : (hasNoResult(entry) ? null : '—')
      }
    },
    {
      title: 'Created',
      dataIndex: 'created_on',
      key: 'created_on',
    },
    {
      title: 'Submitted by',
      dataIndex: 'user',
      key: 'user',
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, entry) => (
        <Space>
          <Tooltip title="Download (ZIP)">
            <Button
              icon={<DownloadOutlined />}
              aria-label={`Download task ${entry.fw_id}`}
              href={`${URL}/task/${entry.fw_id}/download`}
              disabled={entry.state !== 'COMPLETED'}
            />
          </Tooltip>
          <Popconfirm
            title={`Delete task ${entry.fw_id}?`}
            description="This permanently removes the stored result."
            okText="Delete"
            okButtonProps={{ danger: true }}
            cancelText="Cancel"
            onConfirm={() => deleteTask(entry.fw_id)}
            disabled={['READY','RUNNING','CANCELLING'].includes(entry.state)}
          >
            <Button
              danger
              icon={<DeleteOutlined />}
              aria-label={`Delete task ${entry.fw_id}`}
              disabled={['READY','RUNNING','CANCELLING'].includes(entry.state)}
            />
          </Popconfirm>
        </Space>
      ),
    }
  ]

  return (
    <Layout hasSider={false} title="">
      <Container>
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <Search
            placeholder="Filter file name"
            allowClear
            enterButton
            onSearch={onNameSearch}
            defaultValue={name}
            style={{ width: 'min(260px, 45vw)', minWidth: 180 }}
          />
          <Search
            placeholder="Filter username"
            allowClear
            enterButton
            onSearch={onSearch}
            defaultValue={user}
            style={{ width: 'min(260px, 45vw)', minWidth: 180 }}
          />
          <span style={{ flex: 1 }} />
          {selectedTaskIds.length === 0 && <Typography.Text type="secondary">Select 2–20 completed tasks to compare or export.</Typography.Text>}
          {selectedTaskIds.length > 0 && <Button type="link" onClick={() => setSelectedTaskIds([])}>Clear selection</Button>}
          <Button
            icon={<LineChartOutlined />}
            disabled={selectedTaskIds.length < 2}
            href={selectedTaskIds.length >= 2 ? `/compare?tasks=${selectedTaskIds.join(',')}` : undefined}
          >Compare selected ({selectedTaskIds.length})</Button>
          <Button
            icon={<TableOutlined />}
            disabled={!selectedTaskIds.length}
            href={selectedTaskIds.length ? `${URL}/tasks/table.csv?ids=${selectedTaskIds.join(',')}` : undefined}
          >Export table ({selectedTaskIds.length})</Button>
        </div>
        {
          data.tasks ? (
            <Table
              size="small"
              rowKey="fw_id"
              scroll={{ x: 'max-content' }}
              dataSource={data.tasks}
              columns={columns} 
              rowSelection={{
                selectedRowKeys: selectedTaskIds,
                preserveSelectedRowKeys: true,
                onChange: keys => {
                  if (keys.length > 20) message.warning('Compare up to 20 patterns at a time.');
                  setSelectedTaskIds(keys.slice(0, 20));
                },
                getCheckboxProps: record => ({ disabled: record.state !== 'COMPLETED' }),
              }}
              pagination={{
                total: data.total_tasks,
                pageSize: limit,
                current: page,
                onChange: (page, pageSize) => {
                  window.location.href = `/results?` + tasksQuery({ page, limit: pageSize, user, name, selected: selectedTaskIds })
                }
            }}/>
          ) : (
            <p>Loading...</p>
          )
        }
      </Container>

    </Layout>
  )
}

export default ResultsPage;
